	'messages:apihelp-changecontentmodel-param-bot' => 'fr:Marquer la modification du modèle de contenu avec une indication de robot.',
	'messages:apihelp-changecontentmodel-example' => 'fr:Modifier la page principale pour avoir le modèle de contenu <code>text</code>',
	'messages:apihelp-checktoken-summary' => 'fr:Vérifier la validité d’un jeton de <kbd>[[Special:ApiHelp/query+tokens|action=query&meta=tokens]]</kbd>.',
