	'messages:apierror-changecontentmodel-cannot-convert' => 'fr:Impossible de convertir $1 en modèle de contenu $2',
	'messages:apierror-chunk-too-small' => 'fr:La taille minimale d’un segment est de $1 {{PLURAL:$1|octet|octets}} pour les segments hors le dernier.',
	'messages:apierror-cidrtoobroad' => 'fr:Les plages CIDR $1 plus larges que /$2 ne sont pas acceptées.',
